function normalizeStorageKey(value: string): string | null {
  let decoded: string;

  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }

  // Also inspect valid nested encodings, such as %252e%252e, without
  // rejecting a literal percent sign produced by a single decode.
  while (decoded.includes("%")) {
    let additionallyDecoded: string;

    try {
      additionallyDecoded = decodeURIComponent(decoded);
    } catch {
      break;
    }

    if (additionallyDecoded === decoded) {
      break;
    }

    decoded = additionallyDecoded;
  }

  const path = decoded.replaceAll("\\", "/");

  if (!path || path.startsWith("/") || /^[A-Za-z]:\//.test(path)) {
    return null;
  }

  const segments = path.split("/").filter((segment) => segment && segment !== ".");

  if (segments.some((segment) => segment === "..")) {
    return null;
  }

  const normalized = segments.join("/");
  return normalized || null;
}
